{% set ns=namespace(items=[]) %}
{% set sump=states('sensor.aquarium_aquarium_hydros_sump_level_ato') | lower %}
{% set awc = is_state('binary_sensor.aquarium_aquarium_hydros_awc_running','on') or is_state('input_boolean.peninsula_awc_fill_running','on') or is_state('input_boolean.peninsula_awc_drain_running','on') %}
{% if sump == 'overflow' %}{% set ns.items=ns.items+['Sump ATO: Overflow'] %}
{% elif sump == 'dry' and not awc %}{% set ns.items=ns.items+['Sump ATO: Dry'] %}{% endif %}
{% set high=states('sensor.aquarium_aquarium_hydros_sump_too_high') | lower %}
{% if high in ['1','on','wet','high','overflow','true'] %}{% set ns.items=ns.items+['Sump Too High: Wet'] %}{% endif %}
{% set salt=states('sensor.aquarium_aquarium_hydros_make_salt') | lower %}
{% if salt in ['0','off','dry','false'] %}{% set ns.items=ns.items+['Make Salt: Dry'] %}{% endif %}
{% set low=states('sensor.aquarium_aquarium_hydros_rodi_low_level') | lower %}
{% if low in ['0','off','dry','low','false'] %}{% set ns.items=ns.items+['RODI Low: Dry'] %}{% endif %}
{% set tds=states('sensor.aquarium_aquarium_hydros_tds') | float(-9999) %}
{% if tds > 0 %}{% set ns.items=ns.items+['Post DI TDS: ' ~ (tds | round(1)) ~ ' ppm'] %}{% endif %}
{% set temp_level=states('sensor.aquarium_reefcontrol_pro_salinity_62a_temperature_level_2') %}
{% if temp_level != 'desired' %}{% set ns.items=ns.items+['Temperature: ' ~ states('sensor.aquarium_reefcontrol_pro_salinity_62a_temperature_2') ~ ' °F (' ~ (temp_level | replace('_',' ') | title) ~ ')'] %}{% endif %}
{% set ph_level=states('sensor.aquarium_reefcontrol_pro_ph_a4_level_2') %}
{% if ph_level != 'desired' %}{% set ns.items=ns.items+['pH: ' ~ states('sensor.aquarium_reefcontrol_pro_ph_a4_ph_2') ~ ' (' ~ (ph_level | replace('_',' ') | title) ~ ')'] %}{% endif %}
{% set orp_level=states('sensor.aquarium_reefcontrol_pro_orp_285_level_2') %}
{% if orp_level != 'desired' %}{% set ns.items=ns.items+['ORP: ' ~ states('sensor.aquarium_reefcontrol_pro_orp_285_orp_2') ~ ' mV (' ~ (orp_level | replace('_',' ') | title) ~ ')'] %}{% endif %}
{% set sal_level=states('sensor.aquarium_reefcontrol_pro_salinity_62a_level_2') %}
{% if sal_level != 'desired' %}{% set ns.items=ns.items+['Salinity: ' ~ states('sensor.aquarium_reefcontrol_pro_salinity_62a_salinity_2') ~ ' PSU (' ~ (sal_level | replace('_',' ') | title) ~ ')'] %}{% endif %}
{% if is_state('binary_sensor.rscontrolpro_415492340_leak_detector','off') %}{% set ns.items=ns.items+['Leak detected'] %}{% endif %}
{% set status=namespace(items=[]) %}
{% if is_state('binary_sensor.aquarium_aquarium_hydros_awc_running','on') %}{% set status.items=status.items+['AWC ATO/RODI running'] %}{% endif %}
{% if is_state('input_boolean.peninsula_awc_fill_running','on') %}{% set status.items=status.items+['AWC Fill running'] %}{% endif %}
{% if is_state('input_boolean.peninsula_awc_drain_running','on') %}{% set status.items=status.items+['AWC Drain running'] %}{% endif %}
{% set shown=ns.items | unique | list %}
{% set alerts=shown | join(' | ') if shown else 'No active alerts' %}
{% set statuses=status.items | join(' | ') %}
{{ alerts ~ (' · ' ~ statuses if statuses else '') }}

