custom_fields.detail:
[[[
    const sensor = states['binary_sensor.aquarium_rsrun_peninsula_pump_2_controlled_by_sensor'];
    const unavailable = !sensor || ['unknown', 'unavailable'].includes(sensor.state);
    const active = sensor?.state === 'on';
    const label = unavailable ? 'Sensor unavailable' : (active ? 'Sensor' : 'Sensor off');
    const color = unavailable ? '#8a94a3' : (active ? '#45e5a4' : '#ffb547');
    const temp = states['sensor.aquarium_rsrun_peninsula_pump_2_temperature'];
    const value = Number(temp?.state);
    const unit = temp?.attributes?.unit_of_measurement || '';
    const temperature = Number.isFinite(value) ? Math.round(value) + (unit ? ' ' + unit : '') : 'Temp unavailable';
    return '<span>' + label + '</span><span style="width:8px;height:8px;border-radius:50%;background:' + color + ';display:inline-block;margin-left:4px"></span><span style="margin:0 6px">—</span><span>' + temperature + '</span>';
  ]]]

custom_fields.warning:
[[[
    const state = states['sensor.aquarium_rsrun_peninsula_pump_2_state']?.state;
    if (state !== 'over-skimming') return '';
    return '<span style="display:inline-flex;align-items:center"><ha-icon icon="mdi:alert" style="--mdc-icon-size:14px;width:14px;height:14px;flex:0 0 14px"></ha-icon><span style="margin-left:1px">Over-skimming</span></span>';
  ]]]

