custom_fields.dose:
[[[
        const a=Number(states['sensor.aquarium_reefdose4_4_part_head_1_auto_dosed_today']?.state);
        const d=Number(states['sensor.aquarium_reefdose4_4_part_head_1_daily_dose']?.state);
        const mlA=Number.isFinite(a)?a*29.5735:NaN;
        const mlD=Number.isFinite(d)?d*29.5735:NaN;
        return (Number.isFinite(mlA)?mlA.toFixed(1):'—')+' / '+(Number.isFinite(mlD)?mlD.toFixed(1):'—')+' mL';
      ]]]

custom_fields.pills:
[[[
        const done=Number(states['sensor.aquarium_reefdose4_4_part_head_1_doses_today']?.state);
        const total=Number(states['sensor.aquarium_reefdose4_4_part_head_1_daily_doses']?.state);
        const days=Number(states['sensor.aquarium_reefdose4_4_part_head_1_remaining_days']?.state);
        const st=String(states['sensor.aquarium_reefdose4_4_part_head_1_status']?.state||'').toLowerCase();
        const chip=(icon,text,iconColor,bg,border)=>'<span style="display:inline-flex;align-items:center;gap:4px;padding:3px 7px;border:1px solid '+border+';border-radius:9px;background:'+bg+';white-space:nowrap"><ha-icon icon="'+icon+'" style="width:14px;height:14px;color:'+iconColor+'"></ha-icon>'+text+'</span>';
        const neutral=hass.themes?.darkMode?'rgba(255,255,255,0.035)':'rgba(255,255,255,0.42)';
        const neutralBorder='var(--divider-color)';
        if(st==='not-setup') return chip('mdi:flask-empty-outline','Not configured','#718096','transparent',neutralBorder);
        const count=(Number.isFinite(done)?Math.round(done):'—')+' / '+(Number.isFinite(total)?Math.round(total):'—')+' dosed';
        const left=(Number.isFinite(days)?Math.round(days):'—')+' days';
        const dayColor=!Number.isFinite(days)?'#8a8a8a':days<=5?'#ef6471':days<=14?'#f6b84a':'#45d77a';
        const dayBg=!Number.isFinite(days)?neutral:days<=5?(hass.themes?.darkMode?'rgba(239,100,113,0.18)':'rgba(239,100,113,0.13)'):days<=14?(hass.themes?.darkMode?'rgba(246,184,74,0.18)':'rgba(246,184,74,0.14)'):(hass.themes?.darkMode?'rgba(69,215,122,0.16)':'rgba(69,215,122,0.12)');
        const dayBorder=!Number.isFinite(days)?neutralBorder:days<=5?'rgba(239,100,113,0.48)':days<=14?'rgba(246,184,74,0.48)':'rgba(69,215,122,0.44)';
        return chip('mdi:water',count,'#1fa9ff',neutral,neutralBorder)+chip('mdi:battery-medium',left,dayColor,dayBg,dayBorder);
      ]]]

